//! Tables generated by `tools/gen-unicode/` (ADR 0019).

// The Arabic symbol-font maps of HarfBuzz's `src/hb-ot-shaper-arabic-pua.hh`,
// for the cmap remapping of symbol fonts (ADR 0016).
#[rustfmt::skip]
pub(crate) mod arabic_pua;

#[cfg(test)]
mod tests {
    use super::arabic_pua::{simp_map, trad_map};

    #[test]
    fn arabic_pua_maps() {
        assert_eq!(simp_map(0x20), 0xF120);
        assert_eq!(simp_map(0x200C), 0xF10C);
        assert_eq!(simp_map(0x645), 0xF17E);
        assert_eq!(trad_map(0x20), 0xF220);
        assert_eq!(trad_map(0x645), 0xF2C2);
        for cp in [0, 0x41, 0x1F, 0xFEFD, 0x10000, u32::MAX] {
            assert_eq!(simp_map(cp), 0, "{cp:X}");
            assert_eq!(trad_map(cp), 0, "{cp:X}");
        }
    }
}
